import requests

response = requests.post(
    "https://api.aimlapi.com/v1/responses",
    headers={
        "Authorization": "Bearer <YOUR_AIMLAPI_KEY>",
        "Content-Type": "application/json",
    },
    json={'model': 'xiaomi/mimo-v2.6-flash-mopd', 'input': '<input>', 'prompt': 'Describe what you want the model to generate.'},
)

print(response.json())
